def eval_rpn(tokens: list[str]) -> int:
    """Evaluate a reverse Polish notation expression.

    Supports +, -, *, and / where division truncates toward zero.
    """
    stack: list[int] = []
    ops = {"+", "-", "*", "/"}

    for tok in tokens:
        if tok in ops:
            b = stack.pop()
            a = stack.pop()
            if tok == "+":
                stack.append(a + b)
            elif tok == "-":
                stack.append(a - b)
            elif tok == "*":
                stack.append(a * b)
            else:  # "/"
                q = abs(a) // abs(b)
                if (a < 0) ^ (b < 0):
                    q = -q
                stack.append(q)
        else:
            stack.append(int(tok))

    return stack[0]
```

