from collections import Counter

def min_window(s: str, t: str) -> str:
    if not t:
        return ""

    need = Counter(t)
    window = Counter()
    formed = 0
    total = len(need)

    left = 0
    best_len = float("inf")
    best_left = 0

    for right, ch in enumerate(s):
        if ch in need:
            window[ch] += 1
            if window[ch] == need[ch]:
                formed += 1

        while formed == total:
            cur_len = right - left + 1
            if cur_len < best_len:
                best_len = cur_len
                best_left = left

            ch_left = s[left]
            if ch_left in need:
                if window[ch_left] == need[ch_left]:
                    formed -= 1
                window[ch_left] -= 1
            left += 1

    return "" if best_len == float("inf") else s[best_left:best_left + best_len]
