from collections import deque

def course_order(n: int, prereqs: list[list[int]]) -> list[int]:
    graph = [set() for _ in range(n)]
    indegree = [0] * n

    for a, b in prereqs:
        if a not in graph[b]:
            graph[b].add(a)
            indegree[a] += 1

    queue = deque(i for i in range(n) if indegree[i] == 0)
    order = []

    while queue:
        u = queue.popleft()
        order.append(u)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)

    return order if len(order) == n else []
```

